const fs=require('fs'),path=require('path'),crypto=require('crypto'),sharp=require('../../vendor/upscale/node_modules/sharp'),{db}=require('./db'),{DATA_DIR}=require('./paths'),{regionPixels}=require('./refineRegion.cjs');
async function createRefineCrop(tag,region){if(typeof tag!=='string'||tag.length>200)throw Error('Ảnh nguồn không hợp lệ');const row=db.prepare('SELECT * FROM ref_images WHERE tag=?').get(tag);if(!row||row.archived_at||!fs.existsSync(row.filepath))throw Error('Ảnh nguồn không còn trong thư viện');const image=sharp(row.filepath,{limitInputPixels:50000000}).rotate(),buffer=await image.png().toBuffer(),meta=await sharp(buffer).metadata(),rect=regionPixels(region,meta.width,meta.height),digest=crypto.createHash('sha256').update(tag+':'+fs.statSync(row.filepath).mtimeMs+':'+JSON.stringify(rect)).digest('hex').slice(0,24),cropTag='refine_detail_'+digest,existing=db.prepare('SELECT * FROM ref_images WHERE tag=?').get(cropTag);if(existing&&fs.existsSync(existing.filepath))return {tag:cropTag,source:tag,region,originalSize:{width:rect.width,height:rect.height}};const filename=cropTag+'.png',filepath=path.join(DATA_DIR,'uploads',filename);fs.mkdirSync(path.dirname(filepath),{recursive:true});await sharp(buffer).extract(rect).resize({width:Math.min(1600,rect.width*4),height:Math.min(1600,rect.height*4),fit:'inside'}).png().toFile(filepath);if(existing)db.prepare('UPDATE ref_images SET filepath=?,size=?,archived_at=NULL,internal_only=1 WHERE tag=?').run(filepath,fs.statSync(filepath).size,cropTag);else db.prepare("INSERT INTO ref_images(id,tag,filename,filepath,size,mime_type,internal_only,created_at) VALUES(?,?,?,?,?,'image/png',1,datetime('now'))").run(crypto.randomUUID(),cropTag,filename,filepath,fs.statSync(filepath).size);return {tag:cropTag,source:tag,region,originalSize:{width:rect.width,height:rect.height}}}
module.exports={createRefineCrop};
